import{_ as e,o as t,c as n,a2 as r}from"./chunks/framework.mRCPFc5l.js";const m=JSON.parse('{"title":"16. 常见问题","description":"","frontmatter":{},"headers":[],"relativePath":"faq.md","filePath":"faq.md"}'),c={name:"faq.md"};function a(p,o,d,s,g,i){return t(),n("div",null,[...o[0]||(o[0]=[r('<h1 id="_16-常见问题" tabindex="-1">16. 常见问题 <a class="header-anchor" href="#_16-常见问题" aria-label="Permalink to &quot;16. 常见问题&quot;">​</a></h1><p><strong>Q：为什么我有 8 钻石余额，背包里却没有钻石？</strong> A：8 是初始记账余额。用 <code>/bank takeout 8</code> 取出钻石，或直接用它买东西/转账。</p><p><strong>Q：为什么我挖了钻石，余额没变？</strong> A：挖到的钻石是物品，不是余额。需要 <code>/bank add &lt;数量&gt;</code> 存入。</p><p><strong>Q：为什么我不能在自家领地破坏方块？</strong> A：确认你是领地屋主，且没有把自己分配到一个没有 <code>build</code> 权限的组。用 <code>/pclaim info</code> 和 <code>/pclaim explain &lt;领地&gt; build</code> 检查。</p><p><strong>Q：为什么别人能走进我的领地？</strong> A：默认 <code>move=true</code>，领地不是封闭盒子；外人只是不能破坏/开箱子/用按钮。想完全禁止进入，把 <code>move</code> 设为 <code>off</code>。</p><p><strong>Q：为什么我不能开自家箱子？</strong> A：先用 <code>/pclaim explain &lt;领地&gt; container</code> 看是哪条规则拒绝；屋主一般不受成员组限制，若仍被拒绝，检查是否与主城保护区等其他保护重叠。</p><p><strong>Q：为什么领地内不能 PvP？</strong> A：领地默认 <code>pvp=off</code>。屋主可开启；有外人在场时不能改，需要先让对方离开。</p><p><strong>Q：为什么我只能有一块个人领地？</strong> A：当前每人限 1 块。联盟领地是另一套系统，需要加入联盟后使用 <code>/gclaim</code>。</p><p><strong>Q：为什么第 9 个家要收费？</strong> A：前 8 个传送点免费，第 9 个起每个 8 钻石；公开传送点每个 16 钻石。</p><p><strong>Q：为什么 <code>/home</code> 和 <code>/pclaim home</code> 不一样？</strong> A：<code>/home</code> 是个人传送点；<code>/pclaim home</code> 是回自己的领地（优先用 <code>/pclaim settp</code> 设的领地传送点，没设则落领地中心）。两者独立。</p><p><strong>Q：为什么我的联盟一直是 Lv.1？</strong> A：联盟等级固定为 Lv.1，不会增长；人数上限 10、免费领地额度 1,024。扩容只能买额度。</p><p><strong>Q：联盟领地扩容为什么这么贵？</strong> A：按当前价格 100 钻石/格，从联盟金库扣；1 格 100 钻石，256 格 25,600 钻石。建议先用免费 1,024 格，确有必要再买。</p><p><strong>Q：为什么我不能创建联盟领地？</strong> A：需要盟主或拥有 <code>union.claim.create</code> 权限的职位；普通成员只能建造和使用。用 <code>/union rank</code> 检查职位权限。</p><p><strong>Q：死亡会掉东西吗？</strong> A：不会。死亡后背包物品保留；但药水效果、位置和时间仍会损失。</p><p><strong>Q：主世界有多大？</strong> A：有。主世界 100,000 格宽、下界 12,500 格宽、末地 50,000 格宽。</p><p><strong>Q：基岩版名字为什么带 <code>BE-</code>？</strong> A：这是系统给基岩版玩家加的前缀，用于区分 Java 版和基岩版玩家；不影响游戏功能。</p><p><strong>Q：Java 版可以用离线账号吗？</strong> A：不能。服务器要求正版验证，必须使用正版账号。</p><p><strong>Q：想找的功能这里没有怎么办？</strong> A：先看 <a href="./unavailable.html">本服没有的功能</a>，那里列了本服不提供的内容。</p><p><strong>Q：发现 bug 或被骗怎么办？</strong> A：保留截图/录屏、时间、地点和玩家名，联系在线管理员。不要自行利用漏洞。</p>',19)])])}const _=e(c,[["render",a]]);export{m as __pageData,_ as default};
